import type { AnalyticsExportV1 } from './export/v1'
import type { ImportWarning } from './import/importExport'

/**
 * A validated export plus local import metadata.
 *
 * `data` is exactly what the export said (normalized: absent optional fields
 * are `null`). Import metadata is generated by this app and is kept separate so
 * it is never confused with source data from CostcoTracker.
 */
export type LoadedDataset = {
  data: AnalyticsExportV1
  warnings: ImportWarning[]
  meta: {
    /** When this browser imported the file (ISO timestamp, app-generated). */
    importedAt: string
    /** File name as chosen by the user, or a label for the built-in demo. */
    sourceLabel: string
    /** True when the data came from the bundled synthetic demo fixture. */
    isSyntheticDemo: boolean
  }
}
